with RecentWebEvents as (select * from web_events where duration_sec >= 277), summary as (select date_trunc('MONTH', event_time) as event_month, max(event_time) as latest_event_time, round(stddev(duration_sec), 2) as stddev_duration_sec from RecentWebEvents group by date_trunc('MONTH', event_time)) select * from summary where stddev_duration_sec > 55 order by stddev_duration_sec desc, event_month
